package com.fathom.transaction; import com.fathom.common.ResourceNotFoundException; import com.fathom.user.AppUserRepository; import com.fathom.account.FinancialAccountRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.*; import java.util.*; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*;
@RestController public class TransactionController { private final TransactionRepository repo; private final AppUserRepository users; private final FinancialAccountRepository accounts; public TransactionController(TransactionRepository r,AppUserRepository u,FinancialAccountRepository a){repo=r;users=u;accounts=a;} record Req(@NotNull UUID accountId,UUID categoryId,@NotNull LocalDate transactionDate,@NotNull @DecimalMin("0.0") BigDecimal amount,@NotNull Direction direction,@NotNull TransactionType transactionType,@NotNull TransactionSource source,String rawDescription,String merchant,String notes,Boolean internalTransfer,Boolean investmentTransfer,Boolean debtPayment,UUID linkedTransactionId,String importHash){} record Res(UUID id,UUID userId,UUID accountId,UUID categoryId,LocalDate transactionDate,BigDecimal amount,Direction direction,TransactionType transactionType,TransactionSource source,String merchant,Instant createdAt,Instant updatedAt){}
@PostMapping("/api/users/{userId}/transactions") Res create(@PathVariable UUID userId,@Valid @RequestBody Req r){ users.findById(userId).orElseThrow(()->new ResourceNotFoundException("User not found")); accounts.findById(r.accountId()).orElseThrow(()->new ResourceNotFoundException("Account not found")); Transaction t=new Transaction(); t.setUserId(userId); t.setAccountId(r.accountId()); t.setCategoryId(r.categoryId()); t.setTransactionDate(r.transactionDate()); t.setAmount(r.amount()); t.setDirection(r.direction()); t.setTransactionType(r.transactionType()); t.setSource(r.source()); t.setRawDescription(r.rawDescription()); t.setMerchant(r.merchant()); t.setNotes(r.notes()); t.setInternalTransfer(Boolean.TRUE.equals(r.internalTransfer())); t.setInvestmentTransfer(Boolean.TRUE.equals(r.investmentTransfer())); t.setDebtPayment(Boolean.TRUE.equals(r.debtPayment())); t.setLinkedTransactionId(r.linkedTransactionId()); t.setImportHash(r.importHash()); return m(repo.save(t)); }
@GetMapping("/api/users/{userId}/transactions") List<Res> list(@PathVariable UUID userId,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to){ if(from!=null&&to!=null) return repo.findByUserIdAndTransactionDateBetween(userId,from,to).stream().map(this::m).toList(); return repo.findByUserId(userId).stream().map(this::m).toList(); }
@GetMapping("/api/transactions/{transactionId}") Res get(@PathVariable UUID transactionId){ return m(repo.findById(transactionId).orElseThrow(()->new ResourceNotFoundException("Transaction not found"))); }
private Res m(Transaction t){ return new Res(t.getId(),t.getUserId(),t.getAccountId(),t.getCategoryId(),t.getTransactionDate(),t.getAmount(),t.getDirection(),t.getTransactionType(),t.getSource(),t.getMerchant(),t.getCreatedAt(),t.getUpdatedAt()); }}
